insert into categories (slug, name, position) values
  ('pain', 'Pain & fever', 0),
  ('cold', 'Cold, cough & allergy', 1),
  ('vitamins', 'Vitamins', 2),
  ('prescription', 'Prescription medicines', 3),
  ('herbal', 'Herbal & jamu', 4),
  ('firstaid', 'First aid', 5),
  ('devices', 'Health devices', 6);
insert into products (slug, name, generic_name, form, strength, pack, category_id, drug_class, price, max_per_order, image, description, dosage, warnings) values
  ('paracetamol-500', 'Paracetamol 500 mg', 'Paracetamol', 'Tablet', '500 mg', 'Strip of 10 tablets', (select id from categories where slug = 'pain'), 'BEBAS', 8000, null, '/img/paracetamol.jpg', 'Relieves mild to moderate pain such as headache and toothache, and brings down fever.', 'Adults: 1–2 tablets every 4–6 hours, no more than 8 tablets a day.', 'Do not take with other medicines that contain paracetamol.'),
  ('ibuprofen-400', 'Ibuprofen 400 mg', 'Ibuprofen', 'Tablet', '400 mg', 'Strip of 10 tablets', (select id from categories where slug = 'pain'), 'BEBAS_TERBATAS', 12500, 3, '/img/ibuprofen.jpg', 'Anti-inflammatory pain reliever for headache, period pain, muscle pain and fever.', 'Adults: 1 tablet up to 3 times a day after food.', 'P. No. 2: Read the leaflet before use. Not for people with stomach ulcers.'),
  ('cetirizine-10', 'Cetirizine 10 mg', 'Cetirizine dihydrochloride', 'Tablet', '10 mg', 'Strip of 10 tablets', (select id from categories where slug = 'cold'), 'BEBAS_TERBATAS', 15000, 2, '/img/cetirizine.jpg', 'Antihistamine for hay fever, itchy skin and other allergy symptoms.', 'Adults: 1 tablet once a day.', 'P. No. 1: Can cause drowsiness. Do not drive if affected.'),
  ('cough-syrup-dmp', 'Dry Cough Syrup 60 ml', 'Dextromethorphan HBr', 'Syrup', '15 mg/5 ml', 'Bottle of 60 ml with cup', (select id from categories where slug = 'cold'), 'BEBAS_TERBATAS', 22000, 2, '/img/cough-syrup.jpg', 'Calms a dry, tickly cough.', 'Adults: 10 ml three times a day using the measuring cup.', 'P. No. 1: Not for children under 6. Can cause drowsiness.'),
  ('eye-drops-lubricant', 'Lubricating Eye Drops', 'Hypromellose 0.3%', 'Eye drops', '0.3%', 'Bottle of 10 ml', (select id from categories where slug = 'cold'), 'BEBAS_TERBATAS', 18000, 2, '/img/eye-drops.jpg', 'Soothes dry, tired eyes.', '1–2 drops in each eye as needed.', 'P. No. 3: For external use only. Discard 28 days after opening.'),
  ('vitamin-c-1000', 'Vitamin C 1000 mg Effervescent', 'Ascorbic acid', 'Effervescent tablet', '1000 mg', 'Tube of 10 tablets', (select id from categories where slug = 'vitamins'), 'BEBAS', 45000, null, '/img/vitamin-c.jpg', 'Dissolve in water for a daily vitamin C top-up.', '1 tablet a day in a glass of water.', ''),
  ('vitamin-b-complex', 'Vitamin B Complex', 'Thiamine, riboflavin, pyridoxine, cyanocobalamin', 'Tablet', '', 'Strip of 20 tablets', (select id from categories where slug = 'vitamins'), 'BEBAS', 12000, null, '/img/vitamin-b.jpg', 'B vitamins for energy metabolism.', '1 tablet a day after a meal.', ''),
  ('vitamin-d3-drops', 'Vitamin D3 Drops for Kids', 'Cholecalciferol', 'Oral drops', '400 IU/drop', 'Bottle of 10 ml with dropper', (select id from categories where slug = 'vitamins'), 'BEBAS', 98000, null, '/img/vitamin-d-drops.jpg', 'Supports healthy bones and teeth in growing children.', '1 drop a day, on a spoon or in milk.', 'Keep out of reach of children.'),
  ('amoxicillin-500', 'Amoxicillin 500 mg', 'Amoxicillin trihydrate', 'Capsule', '500 mg', 'Strip of 10 capsules', (select id from categories where slug = 'prescription'), 'KERAS', 25000, null, '/img/amoxicillin.jpg', 'Antibiotic for bacterial infections. Prescription only.', 'As prescribed. Finish the whole course.', 'Prescription medicine (Obat Keras). Tell the pharmacist about any penicillin allergy.'),
  ('omeprazole-20', 'Omeprazole 20 mg', 'Omeprazole', 'Capsule', '20 mg', 'Blister of 10 capsules', (select id from categories where slug = 'prescription'), 'KERAS', 30000, null, '/img/omeprazole.jpg', 'Reduces stomach acid for ulcers and reflux. Prescription only.', 'As prescribed, usually once a day before breakfast.', 'Prescription medicine (Obat Keras).'),
  ('amlodipine-5', 'Amlodipine 5 mg', 'Amlodipine besylate', 'Tablet', '5 mg', 'Strip of 10 tablets', (select id from categories where slug = 'prescription'), 'KERAS', 18000, null, '/img/amlodipine.jpg', 'Lowers high blood pressure. Prescription only.', 'As prescribed, once a day.', 'Prescription medicine (Obat Keras). Do not stop suddenly.'),
  ('salbutamol-inhaler', 'Salbutamol Inhaler 100 mcg', 'Salbutamol sulfate', 'Inhaler', '100 mcg/puff', '200 puffs', (select id from categories where slug = 'prescription'), 'KERAS', 85000, null, '/img/salbutamol.jpg', 'Reliever inhaler that opens the airways during asthma symptoms. Prescription only.', '1–2 puffs when needed.', 'Prescription medicine (Obat Keras).'),
  ('budesonide-inhaler', 'Budesonide Inhaler 200 mcg', 'Budesonide', 'Inhaler', '200 mcg/puff', '100 puffs', (select id from categories where slug = 'prescription'), 'KERAS', 180000, null, '/img/budesonide.jpg', 'Preventer inhaler for asthma, used every day. Prescription only.', 'As prescribed, usually twice a day. Rinse mouth after use.', 'Prescription medicine (Obat Keras).'),
  ('jamu-kunyit-asam', 'Jamu Kunyit Asam', 'Turmeric and tamarind', 'Herbal drink', '', 'Glass bottle of 250 ml', (select id from categories where slug = 'herbal'), 'BEBAS', 15000, null, '/img/jamu-kunyit.jpg', 'Traditional Indonesian turmeric and tamarind drink.', 'Drink chilled, 1 bottle a day.', 'Keep refrigerated; best within 3 days of opening.'),
  ('jamu-beras-kencur', 'Jamu Beras Kencur', 'Rice and aromatic ginger', 'Herbal drink', '', 'Glass bottle of 250 ml', (select id from categories where slug = 'herbal'), 'BEBAS', 18000, null, '/img/jamu-botol.jpg', 'Traditional rice and kencur drink, sweetened with palm sugar.', 'Drink chilled, 1 bottle a day.', 'Keep refrigerated.'),
  ('aloe-vera-gel', 'Aloe Vera Gel', 'Aloe barbadensis leaf', 'Gel', '98%', 'Tube of 100 g', (select id from categories where slug = 'herbal'), 'BEBAS', 34000, null, '/img/aloe-gel.jpg', 'Cools and soothes sunburn and dry skin.', 'Apply a thin layer as needed.', 'For external use only.'),
  ('antiseptic-chlorhexidine', 'Chlorhexidine Antiseptic Spray', 'Chlorhexidine gluconate', 'Spray', '0.5%', 'Spray bottle of 100 ml', (select id from categories where slug = 'firstaid'), 'BEBAS', 28000, null, '/img/antiseptic.jpg', 'Cleans small cuts and grazes.', 'Spray on the wound 2–3 times a day.', 'For external use only.'),
  ('plaster-strips', 'Waterproof Plaster Strips', 'Polyurethane plaster', 'Plaster', '', 'Box of 20', (select id from categories where slug = 'firstaid'), 'ALKES', 10000, null, '/img/plaster.jpg', 'Breathable, waterproof plasters for small cuts.', '', ''),
  ('fabric-plaster', 'Fabric Plaster Roll', 'Cotton fabric tape', 'Plaster', '2.5 cm x 5 m', '1 roll', (select id from categories where slug = 'firstaid'), 'ALKES', 14000, null, '/img/wrist-plaster.jpg', 'Flexible tape for dressings on joints.', '', ''),
  ('cotton-balls', 'Cotton Balls', 'Cotton', 'Cotton', '', 'Jar of 100', (select id from categories where slug = 'firstaid'), 'ALKES', 12000, null, '/img/cotton.jpg', 'Soft cotton balls for cleaning and applying lotions.', '', ''),
  ('nitrile-gloves', 'Nitrile Examination Gloves', 'Nitrile', 'Gloves', 'Size M', 'Box of 100', (select id from categories where slug = 'firstaid'), 'ALKES', 95000, 5, '/img/gloves.jpg', 'Powder-free, latex-free disposable gloves.', '', ''),
  ('medical-masks', '3-Ply Medical Masks', 'Polypropylene', 'Mask', '', 'Box of 50', (select id from categories where slug = 'devices'), 'ALKES', 35000, 10, '/img/masks.jpg', 'Three-layer disposable face masks with ear loops.', '', ''),
  ('hand-sanitizer', 'Hand Sanitizer Gel 500 ml', 'Ethanol 70%', 'Gel', '70%', 'Pump bottle of 500 ml', (select id from categories where slug = 'devices'), 'ALKES', 32000, null, '/img/sanitizer.jpg', 'Kills germs on hands without water.', '', 'Flammable. Keep away from fire.'),
  ('digital-thermometer', 'Digital Thermometer', 'Clinical thermometer', 'Device', '', '1 unit with case', (select id from categories where slug = 'devices'), 'ALKES', 55000, null, '/img/thermometer.jpg', 'Reads body temperature in about 60 seconds, with a fever beep.', '', ''),
  ('glass-thermometer', 'Glass Thermometer (Mercury-free)', 'Clinical thermometer', 'Device', '', '1 unit', (select id from categories where slug = 'devices'), 'ALKES', 25000, null, '/img/glass-thermometer.jpg', 'Classic glass thermometer filled with galinstan instead of mercury.', '', ''),
  ('blood-pressure-aneroid', 'Aneroid Blood Pressure Monitor', 'Sphygmomanometer', 'Device', '', 'Cuff, bulb and gauge', (select id from categories where slug = 'devices'), 'ALKES', 285000, null, '/img/blood-pressure.jpg', 'Manual blood pressure monitor with an adult cuff.', '', ''),
  ('pill-organizer', 'Weekly Pill Organizer', 'Plastic pill box', 'Accessory', '', '7 compartments', (select id from categories where slug = 'devices'), 'ALKES', 39000, null, '/img/pill-organizer.jpg', 'One compartment for each day of the week.', '', '');
